# Lanternhold x Grand War: GET /warlinks for the war bot's weekly Lantern Deep scoring (John approved 27 Nov 2026).
# Paste into AWS CloudShell (us-east-1). Updates lanternhold-warden and adds one public, read-only route.
# It lists verified commander links only: commander name, hero name, class, power level, deepest floor, NP+ tier.
# Backs up the current code first. Safe to run twice.
set -e
API=nyu3u8gc73; TS=$(date +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhwarden && cd ~/lhwarden
curl -s "$(aws lambda get-function --function-name lanternhold-warden --query Code.Location --output text)" -o ~/lhbak/lanternhold-warden-$TS.zip
echo "backup: ~/lhbak/lanternhold-warden-$TS.zip"
echo  | base64 -d > index.js
rm -f warden.zip && zip -q warden.zip index.js
aws lambda update-function-code --function-name lanternhold-warden --zip-file fileb://warden.zip >/dev/null
aws lambda wait function-updated --function-name lanternhold-warden
INT=$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /war'].Target" --output text | sed 's#integrations/##')
[ -z "$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /warlinks'].RouteId" --output text)" ] && \
  aws apigatewayv2 create-route --api-id $API --route-key 'GET /warlinks' --authorization-type NONE --target "integrations/$INT" >/dev/null
sleep 3
echo "check:"; curl -s https://$API.execute-api.us-east-1.amazonaws.com/warlinks | head -c 300; echo
echo "Done. Undo: aws lambda update-function-code --function-name lanternhold-warden --zip-file fileb://$HOME/lhbak/lanternhold-warden-$TS.zip"
